style.css:
@-moz-document domain("search.brave.com") {
body {
    background: radial-gradient(circle at top, #1a001a, #000000) !important;
    color: #bb86fc !important;
    font-family: Arial, sans-serif !important;
  }

  input[type="text"],
  input[type="search"] {
    background-color: #121212 !important;
    color: #ffffff !important;
    border: 2px solid #8000ff !important;
    border-radius: 40px !important;
    padding: 10px 20px !important;
    box-shadow: 0 0 10px #8000ff80 !important;
  }

  input::placeholder {
    color: #bb86fc99 !important;
  }
}
